import{_ as d,o as e,c as o,a5 as r}from"./chunks/framework.BEZBAInb.js";const _=JSON.parse('{"title":"介绍","description":"","frontmatter":{"title":"介绍","order":1},"headers":[],"relativePath":"zh/latest/web-tool/guide.md","filePath":"zh/latest/web-tool/guide.md","lastUpdated":1788455378000}'),a={name:"zh/latest/web-tool/guide.md"};function l(i,t,h,s,c,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="konado-webtool" tabindex="-1">Konado WebTool <a class="header-anchor" href="#konado-webtool" aria-label="Permalink to &quot;Konado WebTool&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>Konado WebTool 是一个为 Konado 项目提供 Web 平台开发工具支持的插件。由于 Godot4.x 在 Web 平台上默认会捕获并禁用所有键盘快捷键，导致浏览器的开发者工具快捷键（如 F12、F5 等）无法正常使用，这个插件专门解决了这个问题，允许在 Web 平台上使用常见的浏览器开发者工具快捷键，方便开发者在 Web 环境中进行调试和开发。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>Konado WebTool 通过在 Web 平台上注入 JavaScript 代码来实现快捷键的放行。它会：</p><ol><li>检测当前平台是否为 Web 平台</li><li>如果是 Web 平台且启用了开发者工具支持，则注入快捷键处理代码</li><li>根据配置动态构建允许的快捷键列表</li><li>监听键盘事件，阻止允许的快捷键继续传递给 Godot，同时保留浏览器的默认行为</li></ol><h3 id="与其他解决方案比较" tabindex="-1">与其他解决方案比较 <a class="header-anchor" href="#与其他解决方案比较" aria-label="Permalink to &quot;与其他解决方案比较&quot;">​</a></h3><table tabindex="0"><thead><tr><th>解决方案</th><th>优势</th><th>劣势</th></tr></thead><tbody><tr><td>Konado WebTool</td><td>简单易用、可配置性强、维护性好</td><td>无明显劣势</td></tr><tr><td>手动修改导出模板</td><td>完全控制</td><td>技术要求高，需频繁更新</td></tr><tr><td>开发环境切换</td><td>可在桌面平台调试</td><td>无法捕获 Web 平台特有问题</td></tr></tbody></table><h2 id="支持的浏览器快捷键" tabindex="-1">支持的浏览器快捷键 <a class="header-anchor" href="#支持的浏览器快捷键" aria-label="Permalink to &quot;支持的浏览器快捷键&quot;">​</a></h2><p>这些快捷键规范基于主流浏览器（如 Chrome、Firefox、Edge 等）的开发者工具标准快捷键，参考了各浏览器的官方文档：</p><ul><li><a href="https://developer.mozilla.org/en-US/docs/Tools/Keyboard_shortcuts" target="_blank" rel="noreferrer">Firefox DevTools</a></li><li><a href="https://learn.microsoft.com/en-us/microsoft-edge/devtools-guide-chromium/shortcuts/" target="_blank" rel="noreferrer">Edge DevTools</a></li><li><a href="https://developer.chrome.com/docs/devtools/shortcuts/" target="_blank" rel="noreferrer">Chrome DevTools</a></li><li><a href="https://webkit.org/web-inspector/keyboard-shortcuts/" target="_blank" rel="noreferrer">Safari DevTools（WebKit）</a></li></ul><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th><th>启用选项</th></tr></thead><tbody><tr><td>F12</td><td>打开开发者工具</td><td><code>enable_f12</code></td></tr><tr><td>F5</td><td>刷新页面</td><td><code>enable_f5</code></td></tr><tr><td>F11</td><td>全屏切换</td><td><code>enable_f11</code></td></tr><tr><td>Ctrl+Shift+I (Win/Linux) / Cmd+Opt+I (Mac)</td><td>打开元素面板</td><td><code>enable_ctrl_shift_i</code></td></tr><tr><td>Ctrl+Shift+J (Win/Linux) / Cmd+Opt+J (Mac)</td><td>打开控制台</td><td><code>enable_ctrl_shift_j</code></td></tr><tr><td>Ctrl+Shift+C (Win/Linux) / Cmd+Shift+C (Mac)</td><td>检查元素模式</td><td><code>enable_ctrl_shift_c</code></td></tr><tr><td>Ctrl+U (Win/Linux) / Cmd+U (Mac)</td><td>查看页面源码</td><td><code>enable_ctrl_u</code></td></tr><tr><td>Ctrl+R (Win/Linux) / Cmd+R (Mac)</td><td>刷新页面</td><td><code>enable_ctrl_r</code></td></tr></tbody></table><h2 id="配置选项" tabindex="-1">配置选项 <a class="header-anchor" href="#配置选项" aria-label="Permalink to &quot;配置选项&quot;">​</a></h2><p>在自动加载的 <code>KonadoWebTool</code> 节点中，您可以通过以下属性进行配置：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td><code>developer_shortcuts_enabled</code></td><td>bool</td><td>true</td><td>是否启用 Web 开发者工具快捷键放行</td></tr><tr><td><code>allow_in_release</code></td><td>bool</td><td>false</td><td>是否在正式导出包中启用快捷键放行</td></tr><tr><td><code>enable_f12</code></td><td>bool</td><td>true</td><td>是否启用 F12 快捷键</td></tr><tr><td><code>enable_f5</code></td><td>bool</td><td>true</td><td>是否启用 F5 快捷键</td></tr><tr><td><code>enable_f11</code></td><td>bool</td><td>true</td><td>是否启用 F11 快捷键</td></tr><tr><td><code>enable_ctrl_shift_i</code></td><td>bool</td><td>true</td><td>是否启用 Ctrl+Shift+I 快捷键</td></tr><tr><td><code>enable_ctrl_shift_j</code></td><td>bool</td><td>true</td><td>是否启用 Ctrl+Shift+J 快捷键</td></tr><tr><td><code>enable_ctrl_shift_c</code></td><td>bool</td><td>true</td><td>是否启用 Ctrl+Shift+C 快捷键</td></tr><tr><td><code>enable_ctrl_u</code></td><td>bool</td><td>true</td><td>是否启用 Ctrl+U 快捷键</td></tr><tr><td><code>enable_ctrl_r</code></td><td>bool</td><td>true</td><td>是否启用 Ctrl+R 快捷键</td></tr></tbody></table><p>为了避免在生产环境暴露调试入口，正式导出包默认不安装快捷键处理器。如需在运行时修改配置，请在修改属性后调用：</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KonadoWebTool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">refresh_shortcuts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>',17)])])}const p=d(a,[["render",l]]);export{_ as __pageData,p as default};
